// HasUnitLinks applies the HasEdge predicate on the "unit_links" edge.
func HasUnitLinks() predicate.Party {
	return predicate.Party(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, UnitLinksTable, UnitLinksColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUnitLinksWith applies the HasEdge predicate on the "unit_links" edge with a given conditions (other predicates).
func HasUnitLinksWith(preds ...predicate.UnitParty) predicate.Party {
	return predicate.Party(func(s *sql.Selector) {
		step := newUnitLinksStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Party) predicate.Party {
	return predicate.Party(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Party) predicate.Party {
	return predicate.Party(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Party) predicate.Party {
	return predicate.Party(sql.NotPredicates(p))
}
